INSERT INTO public.legal_cases
  (slug, title, summary, facts, court, image_public_path, reviewer_label, published, sort_order)
VALUES
  ('case-01', 'بيع ساعة يد وتخلص البائع للمشتري', 'شخص اشترى ساعة يد ثم ادّعى طرف ثالث ملكيتها فحكمت المحكمة بثبوت ملكيتها له. هل يحق للمشتري التمسك بالضمان ضد البائع؟', 'بيع «أ» لساعة يد إلى «ب» مقابل ثمن اتفقا عليه، وسلمها إليه وتسلم الثمن كاملا. وبعد ثلاثة أشهر أقام «ج» دعوى أمام المحكمة مدّعيا أن الساعة مسروقة منه، وأرفق شكاية جنائية قديمة وصل فيها إلى قاضي التحقيق. حكمت المحكمة بثبوت ملكية الساعة لـ«ج» وألزمت «ب» بتسليمها، فطالب «ب» «أ» بإرجاع الثمن وتعويضه عن الأضرار. رفض «أ» بدعوى أنه باع «ساعة حلال» كما اشتراها هو نفسه من محل مختص. أمام هذا النزاع، تبيّن أن البائع «أ» ملزم بضمان الخلع وسائر عيوب الحق التي كانت قائمة وقت البيع.', 'قضية مدنية — البيع (قانون الالتزامات والعقود)', '/cases/case-01.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 1),
  ('case-02', 'نقصان في التسليم والتعويض عن الضرر', 'مقاول تعهد بتسليم معدات لمصنع في أجل معين فأخل بالتاريخ، فتوقف الإنتاج. هل يُلزم بالتعويض؟', 'التزم «م» المقاول بموجب عقد بتوريد وتركيب معدات إنتاج لمصنع «ص» في أجل أقصى ثلاثة أشهر، بعقوبة يومية 0.5% من قيمة العقد عن كل يوم تأخير. بعد أربعة أشهر لم يتم التركيب بعد، وتوقف خط الإنتاج عشرة أيام عن العمل، فطالب «ص» بأداء العقوبة اليومية والتعويض عن الخسائر. اعترض «م» بأن التأخير سببه تأخر توريد قطع من مورّد خارجي، وأن توقف الخط كان جزئيا لا كليا.', 'قضية مدنية — المسؤولية العقدية (قانون الالتزامات والعقود)', '/cases/case-02.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 2),
  ('case-03', 'دعوى التشهير في مكان عام', 'نشر «خ» منشورا على موقع إلكتروني يتهم فيه مديرا ماليا بتبديد أموال الشركة. ما تكييف الفعل قانونا؟', 'نشر «خ» على صفحة عامة في شبكة الإنترنت منشورا يتضمن اتهامات معلّلة بأن المدير المالي «د» «استعمل أموال الشركة في مصالحه الخاصة واختلس منها مبالغ مهمة». نشر المنشور على نحو يمكن للعامة الاطلاع عليه، وبلغ عدد منشراته أزيد من خمسة آلاف في أقل من ساعة. أقام «د» شكوى مباشرة ضد «خ» بتهمة التشهير، وطالب بإدانته وبتعويض مدني عن الضرر المعنوي. دفع «خ» بأن ما قاله «حقه في التعبير» وأنه «يصدقه في اتهامه».', 'قضية جنائية — الأفعال المخلة بالشرف (قانون العقوبات)', '/cases/case-03.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 3),
  ('case-04', 'تطليق الزوجة على الزوج لعدم الإنفاق', 'توقف الزوج عن أداء نفقة أسرته لأشهر متتالية. هل يحق للزوجة طلب التطليق قضائيا؟', 'تزوج «س» من «ع» منذ خمس سنوات، ولديهما طفلان. منذ ثمانية أشهر توقف «س» عن أداء أي نفقة لأسرته، رغم أنه يعمل في قطاع خاص بدخل منتظم. طالبته «ع» عدة مرات بالتسديد دون جدوى. قررت «ع» التقدم بطلب إلى المحكمة الابتدائية المختصة تبتغي التطليق على «س» استنادا إلى إخلاله بالتزامات الزوجية، وطلبت في إطار التدابير المؤقتة البت في الحضانة وتأمين سكن مؤقت لها ولأبنائها.', 'قضية أسرة — التطليق (مدونة الأسرة)', '/cases/case-04.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 4),
  ('case-05', 'فسخ عقد كراء شقة سكنية لعلل', 'أخّر المستأجر أداء الكراء أربعة أشهر بعد إنذاره. هل يحق للكائد فسخ العقد؟', 'أكرّت «ن» شقة سكنية إلى «ت» مقابل 3,500 درهم شهريا، بعقد مكتوب يمتد لخمس سنوات. بعد أربعة أشهر من بداية العقد، تأخر «ت» عن أداء الكراء لشهرين متتاليين. أنذره «ن» كتابيا بأداء المبلغ خلال خمسة عشر يوما، فرفض الأداء مبررا ذلك بمشاكل عائلية. بعد انقضاء الأجل، رفعت «ن» دعوى تبتغي فسخ العقد وطرد «ت» من الشقة مع المطالبة بالكراء المتأخر. دفع «ت» بأن «ن» لم تُصلح تسربا في السقف رغم مطالبتها بها.', 'قضية مدنية — الكراء (قانون الالتزامات والعقود)', '/cases/case-05.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 5),
  ('case-06', 'نقل ملكية عقار مسجل دون تسجيل', 'اشترى «ق» عقارا مسجلا في الحفظ العقاري من «ر» ووقعا العقد، لكن لم يتم التسجيل. من يملك العقار تجاه الغير؟', 'اشترى «ق» من «ر» قِطعة أرض مسجلة في الحفظ العقاري، ووقعا على عقد بيع موثق من طرف موثق. لكن «ر» لم يُسجل العقد في الحفظ العقاري، وباع «ر» نفس العقار لـ«ش» في الشهر الموالي، فسجل «ش» العقد في الحفظ العقاري قبل أن يعلم «ق» بالأمر. رفعت «ق» دعوى تدّعي ملكيتها للعقد الأول، وادّعى «ش» أن التسجيل يجعله المالك الحقيقي تجاه الغير.', 'قضية مدنية — الملك والتسجيل العقاري (قانون الالتزامات والعقود)', '/cases/case-06.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 6),
  ('case-07', 'عيب الرضا: الغش في عقد شراء سيارة', 'اشترى «ي» سيارة مستعملة من «ز» الذي أخفى عيبا جوهريا في المحرك. هل يجوز له فسخ العقد؟', 'اشترى «ي» سيارة مستعملة من «ز» بمبلغ 180,000 درهم. أخبره «ز» بأن المحرك «جديد ولم يعرف أي عطل»، وأن السيارة «لم تقطع أكثر من 60,000 كيلومتر». بعد شهر من الشراء، اكتشف «ي» عند زيارة ورشة معتمدة أن المحرك تم استبداله كاملا قبل شهور، وأن كيلومتر السيارة الحقيقية هي 140,000. رفعت «ي» دعوى تبتغي فسخ العقد ومطالبة «ز» بإرجاع الثمن والتعويض. ادّعى «ز» أن «ي» لم يفحص السيارة قبل الشراء، وأن «الغش لا يكون إلا إذا خُفي العيب عمدا».', 'قضية مدنية — عيوب الرضا (قانون الالتزامات والعقود)', '/cases/case-07.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 7),
  ('case-08', 'دعوى إبطال قرار إداري', 'رفضت شركة عامة توظيف «ف» رغم توفرها على الشروط. هل لها دعوى إبطال قرار الرفض أمام المحكمة الإدارية؟', 'نشرت شركة عمومية مباراة توظيف لمجموعة من المناصب، وتقدمت «ف» بملفها مستوفية جميع الشروط المطلوبة. بعد الإعلان عن النتائج، لم يرد اسم «ف» في القائمة، رغم حصولها على الترتيب الثاني في الامتحان الكتابي. توصلت «ف» بمراسلة ترفض توظيفها دون توضيح الأسباب. بعد شهر من توصلها بالمراسلة، قررت «ف» رفع دعوى إبطال أمام المحكمة الإدارية المختصة، مدّعية أن قرار الرفض صدر دون احترام مبدأ الاستحقاق، وأن الترتيب في الامتحان يُثبت أولويتها.', 'قضية إدارية — الطعن في القرارات الإدارية (القانون 41.90)', '/cases/case-08.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 8),
  ('case-09', 'الوصية الواجبة لأحفاد متوفى', 'توفى «ك» عن ابن «ل» الذي مات قبله. هل يستحق أحفاد «ل» وصية واجبة من تركة «ك»؟', 'توفى «ك» بعد حياة زوجية طويلة، تاركا زوجة وثلاثة أبناء: «ل» (توفي قبل «ك» بأربع سنوات)، «م»، و«هـ». كان «ل» له ولدان: «ن» و«س». عند فتح ورثة «ك»، رفضت «م» و«هـ» إعطاء أي حصة لـ«ن» و«س» بحجة أن «الوصية الواجبة لا تطبق إلا على أحفاد الابن الأكبر». قرر «ن» و«س» المطالبة بحقوقهما في تركة «ك» استنادا إلى الوصية الواجبة.', 'قضية أسرة — الوصية الواجبة (مدونة الأسرة)', '/cases/case-09.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 9),
  ('case-10', 'فسخ عقد كراء تجاري والتعويض عن الإخلاء', 'أوقف «و» نشاطه التجاري في قاعة كرائها منذ عشرين سنة بعد فسخ العقد. هل يحق له التعويض عن الإخلاء؟', 'أكرى «و» من «ح» قاعة تجارية في شارع تجاري رئيسي منذ عشرين سنة، واستغلها في نشاط بيع الملابس. بعد عشرين سنة، قرر المالك «ح» فسخ العقد وإعادة استغلال القاعة بنفسه. أرسل «ح» إلى «و» إنذارا بفسخ العقد مع إشعار بستة أشهر. بعد انقضاء الأجل، طالب «ح» «و» بالإخلاء. رافض «و» الإخلاء، وطالب بتعويض عن الإخلاء يشمل: أرباحه المتوقع، قيمة نشاطه التجاري، ومصاريف التجهيزات. ادّعى «ح» أن «الفسخ بموافقة الطرفين لا يُلزم بالتعويض».', 'قضية مدنية — الكراء التجاري (قانون الالتزامات والعقود)', '/cases/case-10.jpg', 'لجنة التوثيق القانونية (بذرة أولى)', true, 10)
INSERT INTO public.legal_case_questions
  (case_slug, position, question, options, answer, explanation)
VALUES
  ('case-01', 1, 'ما المقصود بالتخلص (الخلع) في البيع؟', '["فقدان المشتري المبيع كاملا أو جزئيا بحكم نهائي يثبت حق الغير فيه", "تعذر تسليم المبيع بسبب تلفه عند المشتري", "انقضاء حق المشتري في المطالبة بالثمن بعد مرور مدة", "إبطال البيع بسبب الخداع في الثمن فقط"]'::jsonb, 0, 'التخلص (الخلع) هو فقدان المبيع بحكم نهائي ثابت يثبت حق الغير فيه، سواء كان خلعيا أو جزئيا. وهو من عيوب الحق التي يضمنها البائع للمشتري طبقا للمادة 234 وما يليها من قانون الالتزامات والعقود.'),
  ('case-01', 2, 'ما التزامات البائع الأساسية المنصوص عليها في قانون الالتزامات والعقود؟', '["تسليم المبيع، وضمان سلامته، وضمان الحق (خلع وعيوب الحق)", "تسليم المبيع وضمان سلامته فقط", "تحصيل الثمن وضمان عدم ارتفاع الأسعار", "تسليم المبيع وتحرير وصل بالثمن فقط"]'::jsonb, 0, 'البائع ملزم بتسليم المبيع وضمانه من عيوب الحق (الخلع وعيوب الحق) طبقا للمادة 234 وما بعدها. ضمان الحق يحمي المشتري من فقدان المبيع بسبب حق ثابت للغير.'),
  ('case-01', 3, 'ما الحق الأساسي الذي يمكن للمشتري المخلوع أن يطالب به؟', '["فسخ البيع مع إرجاع الثمن أو التعويض عن الضرر", "الاحتفاظ بالساعة ورفض حكم الملكية", "مطالبة الغريب «ج» بالتعويض دون البائع", "لا حق له لأنه قبض الثمن كاملا"]'::jsonb, 0, 'المشتري المخلوع вправе فسخ البيع واسترداد الثمن مع التعويض عن الأضرار المترتبة على الخلع، ما دام العيب قائما وقت البيع. التعويض يُقدَّر تبعا للضرر المباشر والقطعي.'),
  ('case-02', 1, 'ما الشروط العامة لاستحقاق التعويض عن الضرر؟', '["الخطأ والضرر والعلاقة السببية بينهما", "الضرر فقط، دون حاجة لإثبات خطأ", "الخطأ الإهمالي فقط وليس الخطأ المتعمد", "موافقة المتضرر قبل تقدير التعويض"]'::jsonb, 0, 'التعويض عن الضرر يتطلب توافر ثلاثة شروط: خطأ، ضرر، وعلاقة سببية بينهما (المادة 270 من قانون الالتزامات والعقود). إذا وقع أحد هذه الشروط لا تقوم المسؤولية.'),
  ('case-02', 2, 'ما مدى التزام المدين بالأداء في موعده؟', '["المدين ملزم بالأداء في الأجل المتفق عليه، والتأخير يُعد نفيا للالتزام", "المدين غير ملزم ما لم يُلزم بحكم قضائي", "التأخير لا يُعد نفيا إلا بعد شهر من الإنذار", "التزام بالأداء يسقط بعد مرور سنة واحدة"]'::jsonb, 0, 'عقد الالتزام ملزم للأطراف (المادة 230 وما بعدها). التأخر في الأداء بعد الأجل المتفق عليه يُعد نفيا للالتزام، ويُجيز للمدّان المطالبة بالتعويض، خاصة إذا اتُّفقت على عقوبة يومية.'),
  ('case-02', 3, 'هل يُعفى المقاول من المسؤولية بحجة تأخر مورّده الخارجي؟', '["لا، إلا إذا كان التأخير بسبب قوة قاهرة أو خطأ الغير المدين معه", "نعم، فالقوة القاهرة تقطع المسؤولية دوما", "نعم، فالعقود لا تُنفذ تجاه الموردين", "لا، فالقوة القاهرة غير معترف بها أصلا"]'::jsonb, 0, 'تأخر مورّد خارجي لا يُعد قوة قاهرة من ذات المعنى القانوني، خاصة إذا كان يمكن للمقاول أن يتوقعه أو يتجنبه. المسؤولية تُسقط فقط بسبب القوة القاهرة أو خطأ الغير الذي لم يكن للمدين أن يتوقعه أو يدفعه (المادة 305 وما بعدها من قانون الالتزامات والعقود).'),
  ('case-03', 1, 'ما التمييز القانوني بين القذف والسب في قانون العقوبات المغربي؟', '["القذف هو نسبة فعل يمس بالشرف، والسب هو شتم وشتيمة دون نسبة فعل محدد", "لا فرق بينهما، وكلاهما من الأفعال المخلة بالشرف فقط", "القذف يُقصد به الموظفون العموميون فقط", "السب أشد من القذف ويوجب العقوبة الأشد دوما"]'::jsonb, 0, 'يُعرّف القانون المغربي القذف بأنه نسبة فعل يمس بالشرف (المادة 447)، بينما السب هو شتم وشتيمة دون نسبة فعل محدد. في هذه القضية، اتهام «د» بالاستعمال الشخصي لأموال الشركة يُعد نسبة فعل يمس بالشرف، أي قذفا.'),
  ('case-03', 2, 'هل يُعفي «خ» من المسؤولية بحجة أنه «يصدقه في اتهامه»؟', '["لا، فالدفاع بحقيقة الأمر مقصور على حالات محددة في القانون", "نعم، فإذا كان الاتهام صادقا فلا جريمة", "نعم، لأن حرية التعبير مطلقة على الإنترنت", "لا، لأن الإنترنت لا يندرج تحت قانون العقوبات"]'::jsonb, 0, 'الدفاع بحقيقة الأمر (التمسك بصحة الادعاء) مقصور قانونا على حالات محددة، ولا يجوز استعماله إلا وفق شروط دقيقة. مجرد «الاعتقاد» بصحة الاتهام لا يُسقط المسؤولية، خاصة إذا نُشر في مكان يمكن للعامة الاطلاع عليه.'),
  ('case-03', 3, 'ما أثر النشر في مكان يمكن للعامة الاطلاع عليه؟', '["يُعد ظرفا تشديدا يعرّض الفاعل لعقوبة أشد", "لا أثر له على العقوبة", "يُحوّل القذف إلى مسألة مدنية بحتة", "يعفي الفاعل من العقوبة لأنه مارس حقه في التعبير"]'::jsonb, 0, 'نشر القذف أو السب في مكان يمكن للعامة الاطلاع عليه (لافتات، مواقع إلكترونية، تجمع عام) يُعد ظرفا تشديدا يُعرّض الفاعل لعقوبة أشد طبقا للمادة 448 من قانون العقوبات.'),
  ('case-04', 1, 'ما الأساس القانوني الذي يجوز له أن تتقدم به «ع» بطلب التطليق؟', '["المادة 94 من مدونة الأسرة: التطليق لعدم الإنفاق أو الإخلال بالتزامات الزوجية", "المادة 66 من مدونة الأسرة: الخلع", "المادة 117 من مدونة الأسرة: الشقاق", "المادة 40 من مدونة الأسرة: الطلاق بالتراضي"]'::jsonb, 0, 'المادة 94 من مدونة الأسرة تبيح للزوجة طلب التطليق على زوجها عند الإخلال بالتزامات الزوجية، من بينها عدم الإنفاق. وهي من أهم وسائل الحماية التي تمنحها المدونة للزوجة.'),
  ('case-04', 2, 'ما الإجراء الذي يتخذه القاضي قبل الحكم بالتطليق في حالة عدم الإنفاق؟', '["يُحذّر الزوج ويمنحه أجلا لا يتجاوز شهرين لأداء النفقة، فإن لم يفعل حكم بالتطليق", "يُحكم بالتطليق فور تقديم الطلب", "يُحكم بالتعويض المالي فقط دون التطليق", "يُحيل الملف إلى مجلس العائلة ليبت فيه"]'::jsonb, 0, 'طبقا للمادة 94، يُحذّر القاضي الزوج ويمنحه أجلا لا يتجاوز شهرين لأداء النفقة الواجبة. إذا لم ينفذ، حكم بالتطليق بائنا، وتحفظ الزوجة جميع حقوقها الشرعية.'),
  ('case-04', 3, 'هل يسقط حق «ع» في التطليق إذا لم يطلب التدابير المؤقتة أول الأمر؟', '["لا، فطلب التطليق قائم بذاته ولو لم يطلب التدابير المؤقتة", "نعم، فالتدابير المؤقتة شرط جوهري لقبول الدعوى", "نعم، فلا يجوز الجمع بين التطليق وتكاليف السكن", "لا، لكن فقط إذا وافق الزوج خطيا"]'::jsonb, 0, 'التدابير المؤقتة (السكن، الحضانة، النفقة أثناء النزاع) من حقوق الزوجة أثناء النزاع (المادة 121)، لكن عدم طلبها لا يُسقط حقها في طلب التطليق على الزوج استنادا إلى عدم الإنفاق.'),
  ('case-05', 1, 'ما التزامات الكائد الأساسية المنصوص عليها في قانون الالتزامات والعقود؟', '["تسليم الشيء المكروب وضمان استغلاله الهاديء وضمان عيوب الشيء", "تحصيل الكراء وضمان عدم ارتفاع الأسعار", "تسليم الشيء وضمان عدم رفع الكراء", "تحرير عقد مكتوب وضمان تسجيله"]'::jsonb, 0, 'الكائد ملزم بتسليم الشيء المكروب، وضمان استغلاله الهاديء، وضمان عيوب الشيء التي تمنع الاستغلال (المادة 439 وما بعدها). إذا أخلف الكائد التزامه بالإصلاح، يحق للمستأجر التمسك بحق الرد بالوفاء.'),
  ('case-05', 2, 'هل يكفي إخلال «ت» بالأداء دون إنذار لفسخ العقد؟', '["لا، ففسخ العقد لأجل عدم الأداء يتطلب إنذارا رسميا بأجل معقول", "نعم، فكل تأخير عن الأداء يُسقط العقد آليا", "نعم، لكن فقط إذا كان التأخير سنة كاملة", "لا، فيجب الحصول على حكم قضائي أول قبل الإنذار"]'::jsonb, 0, 'طبقا للمادة 441 وما بعدها، لا يُفسخ عقد الكراء لأجل عدم الأداء إلا بعد إنذار المستأجر بأجل معقول. في هذه القضية، أنذرت «ن» «ت» كتابيا، فكان الإخلال ثابتا بعد انقضاء الأجل.'),
  ('case-05', 3, 'هل يُعفي «ت» من أداء الكراء بحجة أن «ن» لم تُصلح التسريب؟', '["لا، فالأداء واجب إلا إذا ثبت أن العيب يمنع الاستغلال جوهريا، ولو جاز له طلب الرد", "نعم، فكل عيب يعفي من الأداء بالكامل", "نعم، لأن الكائد ملزم بالإصلاح قبل تحصيل الكراء", "لا، فالإصلاح لا علاقة له بعقد الكراء"]'::jsonb, 0, 'حق الرد بالوفاء (المادة 450 وما بعدها) لا يُسقط واجب الأداء إلا إذا كان العيب جوهريا يمنع الاستغلال. تسريب في السقف قد يُعد عيبا يستوجب الإصلاح، لكنه لا يُعفي المستأجر من أداء الكراء بالكامل ما دام الاستغلال ممكنا.'),
  ('case-06', 1, 'متى تنتقل ملكية العقار المسجل؟', '["بتسجيل العقد في الحفظ العقاري، لا بمجرد اتفاق الطرفين", "بمجرد توقيع العقد بين الطرفين", "بمضي سنة على توقيع العقد", "بمطالبة المشتري بتسجيل العقد بعد مرور ثلاثة أشهر"]'::jsonb, 0, 'طبقا للمادة 942 وما بعدها من قانون الالتزامات والعقود، لا تنتقل ملكية العقار المسجل إلا بتسجيل العقد في الحفظ العقاري. العقد بين «ر» و«ق» صحيح بينهما، لكنه غير نافذ في مواجهة الغير ما لم يُسجل.'),
  ('case-06', 2, 'ما أثر عدم تسجيل العقد بين «ر» و«ق» في مواجهة «ش»؟', '["العقد غير نافذ في مواجهة الغير المسجل، فيعتبر «ش» المالك الحصري تجاه الغير", "العقد نافذ في مواجهة جميع الغير بمجرد التوقيع", "لا أثر للتسجيل على ملكية العقار", "ينفد العقد فقط إذا كان «ش» غير مسجل"]'::jsonb, 0, 'التسجيل في الحفظ العقاري هو وسيلة النشر في الملك العقاري. بما أن «ش» سجل عقده قبل أن يعلم «ق»، فإن «ش» يكون المالك الحصري تجاه الغير. «ق» يحق له أن يُلزم «ر» بالتعويض عن الخسران الذي تسبب فيه بعدم التسجيل.'),
  ('case-06', 3, 'ما الحق الذي يملكه «ق» بعد خسرانه الملكية؟', '["مطالبة «ر» بالتعويض عن الخسران، أو فسخ العقد واسترداد الثمن", "لا حق له لأنه باع ثمنه بالكامل", "مطالبة «ش» بإرجاع العقار", "مطالبة الدولة بالتعويض"]'::jsonb, 0, 'بما أن «ر» أخل بالتزامه بالتسجيل وتسبب في خسارة «ق» الملك، يحق لـ«ق» فسخ العقد واسترداد الثمن مع التعويض عن الضرر، طبقا للمادة 231 وما بعدها من قانون الالتزامات والعقود.'),
  ('case-07', 1, 'ما تعريف الغش (التدليس) في قانون الالتزامات والعقود؟', '["مخادعة من دونها لما كان الطرف الآخر يعقد إياه", "كل خطأ في تقدير قيمة المبيع", "إخفاء عيب يسير لا يمنع استعمال الشيء", "تغيير الثمن بعد توقيع العقد"]'::jsonb, 0, 'الغش هو مخادعة من دونها لما كان الطرف الآخر يعقد إياه (المادة 52 من قانون الالتزامات والعقود). في هذه القضية، إخفاء «ز» لاستبدال المحرك الكامل وتضليله في كيلومتر السيارة يُعد غشا جوهريا.'),
  ('case-07', 2, 'ما الحق الذي يملكه «ي» بعد إثبات الغش؟', '["فسخ العقد مع استرداد الثمن والتعويض عن الضرر", "لا حق له لأنه لم يفحص السيارة", "خفض الثمن بنسبة 10% فقط", "إبقاء العقد مع المطالبة بإصلاح العيب فقط"]'::jsonb, 0, 'طبقا للمادة 53 وما بعدها، إذا ثبت الغش الجوهري، يحق للطرف المتضرر فسخ العقد واسترداد ما أدّاه مع التعويض عن الضرر. إهمال «ي» في الفحص لا يُعفي «ز» من المسؤولية ما دام الغش متعمدا.'),
  ('case-07', 3, 'هل يكفي «اعتقاد» «ز» بأنه لا يخفي أي عيب لإسقاط مسؤوليته؟', '["لا، فالغش يتحقق بالإخفاء أو التضليل العمدي، ولا يُسقطه اعتقاد الفاعل", "نعم، فإذا كان «ز» حسن النية فلا غش", "نعم، لأن الغش لا يكون إلا في العقارات", "لا، لكن فقط إذا ثبت أن «ز» عرف العيب قبل سنة"]'::jsonb, 0, 'مسؤولية الغش لا تسقط بمجرد «الاعتقاد» بعدم وجود عيب. إذا ثبت أن «ز» كان على علم باستبدال المحرك وتضليله في كيلومتر السيارة، فذلك يُعد غشا عمديا يُسقطه عن المسؤولية.'),
  ('case-08', 1, 'ما الاختصاص الطبيعي لبحث دعوى إبطال قرار إداري؟', '["المحكمة الإدارية طبقا للقانون 41.90", "المحكمة الابتدائية", "المحكمة التجارية", "العدل والمظالم"]'::jsonb, 0, 'طبقا للقانون 41.90 بإحداث المحاكم الإدارية، تختص المحاكم الإدارية بنظر الدعاوى الإدارية، من بينها دعاوى إبطال القرارات الإدارية. دعوى «ف» أمام المحكمة الابتدائية لن تكون مقبولة.'),
  ('case-08', 2, 'ما الأجل القانوني لرفع دعوى إبطال قرار إداري؟', '["أربعة أشهر من تاريخ إشعار المتضرر بالقرار", "شهران من تاريخ إشعار المتضرر", "سنة من تاريخ إشعار المتضرر", "لا يوجد أجل محدد"]'::jsonb, 0, 'طبقا للقانون 900.03 بمثابة قانون المسطرة الإدارية، يُرفع الطعن في القرار الإداري داخل أجل أربعة أشهر من تاريخ إشعار المعني بالأمر بالقرار أو من تاريخ نشره إذا كان موجها إلى العموم.'),
  ('case-08', 3, 'ما الأساس القانوني الذي يمكن لـ«ف» أن تستند عليه في دعواها؟', '["مخالفة مبدأ الاستحقاق والتمييز غير المبرر في التوظيف", "عدم توفرها على الشروط", "انعدام اختصاص الشركة في التوظيف", "انعدام وجود مباراة توظيف"]'::jsonb, 0, 'مبدأ الاستحقاق من المبادئ الأساسية في التوظيف في الوظيفة العمومية والمؤسسات العمومية. إذا ثبت أن «ف» حصلت على الترتيب الثاني دون مبرر قانوني لإقصائها، فإن قرار الرفض يكون متعسفا ويُقبل إبطاله.'),
  ('case-09', 1, 'من يستحق الوصية الواجبة طبقا للمادة 369 من مدونة الأسرة؟', '["أحفاد الابن أو البنت الذين ماتوا قبل أصلهم المتوفى", "أحفاد الابن الأكبر فقط", "الأحفاد الذين تجاوزوا سن الرشد", "الأحفاد الذين لم يرثوا شيئا من تركة جدّهم"]'::jsonb, 0, 'طبقا للمادة 369 من مدونة الأسرة، يستحق الوصية الواجبة أحفاد الابن أو البنت الذين ماتوا قبل أصلهم المتوفى، سواء كانوا من ذرية الابن أو البنت. في هذه القضية، «ن» و«س» أحفاد «ل» الذي مات قبل «ك»، فهم يستحقون الوصية الواجبة.'),
  ('case-09', 2, 'ما مقدار الوصية الواجبة لـ«ن» و«س»؟', '["حصة «ل» لو كان حيا، إلى غاية ثلث تركة «ك»", "ثلث تركة «ك» بالكامل", "نصف حصة «م» و«هـ»", "ربع تركة «ك»"]'::jsonb, 0, 'طبقا للمادة 370، تكون الوصية الواجبة بمقدار الحصة التي كان يستحقها «ل» لو كان حيا وقت وفاة «ك»، على ألا يتجاوز ذلك ثلث التركة. في هذه القضية، لو كان «ل» حيا لاستحق حصة تساوي حصة كل واحد من «م» و«هـ»، أي الثلث.'),
  ('case-09', 3, 'هل يُسقط حق «ن» و«س» في الوصية الواجبة كونهما لم يرثا شيئا من تركة «ك»؟', '["لا، فعدم المباشرة في الإرث هو بالضبط الذي يبرر الوصية الواجبة", "نعم، فعدم المباشرة في الإرث يُسقط حق الوصية", "نعم، لكن فقط إذا كان أحدهما راشدا", "لا، لكن فقط إذا وافق باقي الورثة"]'::jsonb, 0, 'عدم المباشرة في الإرث هو سبب الوصية الواجبة، لا مُسقط لها. «ن» و«س» لم يرثا من «ك» مباشرة لأن ابنهما «ل» مات قبله، ولذلك خُصصت لهما الوصية الواجبة كتعويض عن هذا الانقطاع في سلسلة الإرث.'),
  ('case-10', 1, 'ما الحق الذي يملكه المستأجر التجاري عند الإخلاء دون خطأ منه؟', '["التعويض عن الأرباح المتوقع عن النشاط التجاري", "لا حق له في التعويض إذا فُسخت العقد بالتراضي", "حق بقاء في القاعة إلى أجل غير مسمى", "الاحتفاظ بالقاعة مع رفع الكراء"]'::jsonb, 0, 'طبقا للمادة 446 وما بعدها من قانون الالتزامات والعقود، يحق للمستأجر التجاري أن يتحصل على تعويض عن الأرباح المتوقع عند الإخلاء دون خطأ منه، شريطة أن يكون قد استغل القاعة لمدة كافية.'),
  ('case-10', 2, 'ما الشروط التي يجب أن تتوافر لإثبات التعويض عن الإخلاء؟', '["وجود نشاط تجاري فعلي، واستغلال مستمر، وعدم وجود خطأ من المستأجر", "موافقة المالك على الاستمرار فقط", "مرور سنة واحدة على الكراء كحد أدنى", "حيازة عقد كراء مكتوب مسجل"]'::jsonb, 0, 'التعويض عن الإخلاء يتطلب توافر عدة شروط: وجود نشاط تجاري فعلي، استغلال مستمر للقاعة، وعدم وجود خطأ من المستأجر أدى إلى الفسخ. في هذه القضية، «و» استغل القاعة لعشرين سنة دون أي خطأ منه.'),
  ('case-10', 3, 'هل يشمل التعويض عن الإخلاء مصاريف التجهيزات والنشاط؟', '["نعم، إذا كانت التجهيزات خاصة بالنشاط التجاري ولا يمكن نقلها", "لا، فالنشاط التجاري لا يُعوض", "نعم، لكن فقط إذا تجاوزت قيمتها 100,000 درهم", "لا، فالإخلاء يُعوض بالثمن فقط"]'::jsonb, 0, 'التعويض عن الإخلاء يشمل الأرباح المتوقع عن النشاط التجاري، ومصاريف التجهيزات الخاصة بالنشاط التي لا يمكن نقلها، والنفقات التي أنفقها «و» على تطوير النشاط. لا يشمل التعويض قيمة القاعة نفسها أو حق الملكية.');
