-- =====================================================================
-- بذرة بنك القضايا القانونية: 10 قضية، 30 سؤال.
-- مولّدة آليا من data/cases/cases.json عبر data/cases/build_cases_seed.py.
-- idempotent: ON CONFLICT (slug) DO NOTHING + حذف أسئلة البذرة السابقة.
-- =====================================================================
BEGIN;

ON CONFLICT (slug) DO NOTHING;

DELETE FROM public.legal_case_questions WHERE case_slug IN ('case-01', 'case-02', 'case-03', 'case-04', 'case-05', 'case-06', 'case-07', 'case-08', 'case-09', 'case-10');


COMMIT;
